WITH base AS (SELECT id, channel, promo_code, starts_on, discount_pct, LENGTH(promo_code) AS promo_code_length, COALESCE(channel, 'DIRECT') AS resolved_channel FROM promotions WHERE starts_on > DATE '2023-12-02' AND channel IS NOT NULL) SELECT s.*, pr.id AS promo_id, pr.promo_code AS promotion_promo_code, pr.discount_pct AS promotion_discount_pct FROM base s INNER JOIN promotions pr ON COALESCE(s.channel, 'store') = pr.channel AND s.starts_on BETWEEN pr.starts_on AND pr.ends_on
